export interface PrinterInfo {
  id: string;
  name: string;
  kind: PrinterKind;
  // The card menu's items; one the host sends as false is shown disabled.
  canOpenSettings: boolean;
  canRename: boolean;
  canRemove: boolean;
  state: PrinterState;
  // Host-formatted status line, e.g. "Printing · 43% · 2h left". Present
  // whenever the host has something to say about the current job.
  statusText?: string;
  // 0-100, present only while printing; drives the progress bar's width.
  progressPercent?: number;
  connectionState: ConnectionState;
  // Host-formatted Connection row, e.g. "Online · LAN", "Not connected".
  connectionText?: string;
  connectionKind?: ConnectionKind;
  connectionAction?: 'reconnect';
  // A print host's address as saved, without its scheme.
  address?: string;
  // Host-formatted Model row, e.g. "X1 Carbon · 0.4 mm".
  modelText?: string;
  spools: SpoolInfo[];
  // A Bambu card's Launch monitor, or a print host's Open printer window.
  canLaunchMonitor: boolean;
  // What was made for, sent to and printed on this printer, across projects;
  // absent when nothing was.
  history?: HistorySummary;
}

// Which screen the page shows, as the host asks when Home comes on screen:
// the gallery, or a Print history the project opened, filtered to it, which
// Back leaves for the project again.
export type ScreenPayload =
  | { screen: 'home' }
  | { screen: 'history'; projectId?: string; focus?: string; back: 'project' };

// Where a G-code went. An exported file is checked against what was written
// each time the screen asks; a send is never verified like a file.
export type HistoryDestination =
  | { id: string; kind: 'export'; at: string; path: string; check: 'matches' | 'changed' | 'missing' }
  | {
      id: string;
      kind: 'send';
      at: string;
      printerName: string;
      // The printer card it went to, when Home has one.
      printerId?: string;
      // The transport reported the file on the printer.
      delivered: boolean;
      // The send also asked the printer to start.
      startRequested: boolean;
    };

// A print, only as the printer reported it.
export interface HistoryPrint {
  id: string;
  printerName: string;
  printerId?: string;
  startedAt: string;
  finishedAt?: string;
  // Present while the printer is running this print.
  live?: { percent?: number; remainingSeconds?: number };
}

// One G-code that left a project: the screen's entry.
export interface HistoryEntry {
  projectId: string;
  projectName: string;
  // SHA-256 of the G-code; the page shows its first eight digits.
  hash: string;
  // The exported file's name, else the plate's.
  name: string;
  plateName: string;
  createdAt: string;
  printTimeSeconds?: number;
  grams?: number;
  layers?: number;
  // The presets it was made with, as the person sees them.
  printer?: string;
  material?: string;
  process?: string;
  // The chat and marker where it first went out.
  conversationId?: string;
  markerId?: string;
  // Whether the project still keeps an intact copy to export.
  kept: boolean;
  // Whether Print again can send the kept file to the printer selected now.
  // 'not_for_this_printer': kept, but not as that printer takes it (a Bambu
  // printer takes the package only a Bambu send keeps). 'changed': the kept
  // file no longer holds what was kept, and is never sent.
  printAgain: 'ready' | 'not_kept' | 'not_for_this_printer' | 'no_printer' | 'changed';
  // Every printer card it belongs to: made for, sent to or printed on.
  printerIds: string[];
  destinations: HistoryDestination[];
  prints: HistoryPrint[];
  // The report the person sent: that it exists and what it earned, never how
  // the print went.
  report?: { sentAt: string; credits: number };
}

export interface HistoryPayload {
  entries: HistoryEntry[];
  // Reports earn credits, so they need the person's account.
  reportsOffered?: boolean;
}

export interface PrintReportPhoto {
  id: string;
  name: string;
  sizeBytes: number;
  // A data URL; absent when the host could not draw the file.
  thumbnail?: string;
}

export type PrintReportOutcome = 'worked' | 'partly' | 'failed';

export interface PrintReportResult {
  hash: string;
  state: 'sent' | 'already_sent' | 'failed';
  credits: number;
}

// A printer action the host understood but could not carry out, such as a
// name another profile already has. The message is translated.
export interface PrinterErrorPayload {
  id: string;
  message: string;
}


// A question the host asks before an action it cannot take back, drawn as
// the design system's Confirmation dialog: a calibration that saves and
// closes the open project. The answer goes back with its requestId.
export interface ConfirmPayload {
  requestId: string;
  title: string;
  body: string;
  confirm: string;
  cancel: string;
}

export interface StatePayload {
  appearance: Appearance;
  projects: ProjectInfo[];
  // Host-formatted and already translated; non-empty when the saved projects
  // could not be read, which the gallery says instead of its empty-gallery line.
  projectsProblem?: string;
  printers: PrinterInfo[];
  // A printer the conversation just added; empty for any other push.
  highlightPrinter?: string;
  onboarding: OnboardingState;
}

export type OnboardingStep = 'hidden' | 'welcome' | 'profiles' | 'confirm_setup' | 'setup' | 'project';

export interface OnboardingState {
  visible: boolean;
  step: OnboardingStep;
  status: 'unfinished' | 'completed' | 'dismissed';
  agentConfigured: boolean;
  profiles: {
    available: boolean;
    imported: boolean;
    partialImportPending: boolean;
    failed: string[];
    printerCount: number;
    filamentCount: number;
    processCount: number;
    source: string;
    // Preset names found in the source, per kind, for reviewing a selection.
    printerNames?: string[];
    filamentNames?: string[];
    processNames?: string[];
    // After an import that left some presets behind: the ones that were
    // copied, named like `failed` as "<directory>/<file>.json".
    importedFiles?: string[];
  };
  setup: {
    usable: boolean;
    offlineExample: boolean;
    summary: string;
    printer: string;
    nozzle: string;
    plate: string;
    material: string;
    process: string;
  };
  projectOpen: boolean;
}

export interface Envelope<T = unknown> {
  protocol: string;
  version: number;
  id: string;
  type: string;
  correlationId?: string;
  payload: T;
}

export function isEnvelope(value: unknown): value is Envelope {
  if (typeof value !== 'object' || value === null) return false;
  const env = value as Record<string, unknown>;
  return (
    env.protocol === PROTOCOL_NAME &&
    typeof env.version === 'number' &&
    typeof env.id === 'string' &&
    typeof env.type === 'string'
  );
}
// Home's state and the one reducer that advances it. The page renders what the
// host last said; it owns no project or printer state of its own, so a reload
// is always recoverable from the next `state` envelope.

import type { ConnectionState } from '../bridge/client';
import type {
  Appearance,
  ConfirmPayload,
  Envelope,
  HistoryEntry,
  HistoryPayload,
  PrinterErrorPayload,
  PrinterInfo,
  ProjectInfo,
  ScreenPayload,
  StatePayload,
  OnboardingState,
  PrintReportPhoto,
  PrintReportResult,
} from '../bridge/protocol';

// Home's two screens. Print history is always a leaf: Back returns to the
// gallery when the gallery opened it, and to the project when the project did.
// Where it was opened from sets its first filter.
export type Screen =
  | { kind: 'home' }
  | { kind: 'history'; back: 'home' | 'project'; projectId?: string; printerId?: string; focus?: string };

export interface HomeState {
  connection: ConnectionState;
  connectionDetail?: string;
  // Absent until the host answers the handshake with state: an empty gallery
  // and "no projects yet" are different screens.
  loaded: boolean;
  appearance: Appearance;
  projects: ProjectInfo[];
  // Why there are no projects to show, when they could not be read.
  projectsProblem?: string;
  printers: PrinterInfo[];
  error?: string;
  // The last printer action the host refused. The host follows a refusal with
  // a fresh state, so only the person's next printer action clears it.
  printerError?: PrinterErrorPayload;
  // A printer the conversation just added, which the host leads the column
  // with for this one push; its card draws attention to itself once.
  highlightPrinter?: string;
  // The host's open question, until the person answers it.
  confirmation?: ConfirmPayload;
  screen: Screen;
  // The Print history's entries, as the host last sent them; absent until
  // the first arrives. The page asks again each time the screen opens and
  // each time the host's state changes under it.
  history?: HistoryEntry[];
  reportsOffered?: boolean;
  // The print report form's photo and the server's answer, while it is open.
  reportPhoto?: PrintReportPhoto;
  reportResult?: PrintReportResult;
  // Counts the host's state pushes, so the open history can follow them.
  stateCount: number;
  onboarding?: OnboardingState;
  onboardingError?: string;
}

export const initialState: HomeState = {
  connection: 'connecting',
  loaded: false,
  appearance: 'light',
  projects: [],
  printers: [],
  screen: { kind: 'home' },
  stateCount: 0,
};

export type HomeAction =
  | { kind: 'connection'; state: ConnectionState; detail?: string }
  | { kind: 'envelope'; envelope: Envelope }
  | { kind: 'printer_action' }
  | { kind: 'confirmation_answered' }
  | { kind: 'show'; screen: Screen }
  | { kind: 'report_form_reset' }
  | { kind: 'report_sending' }
  | { kind: 'onboarding_action' };

export function reduce(state: HomeState, action: HomeAction): HomeState {
  if (action.kind === 'connection') {
    return { ...state, connection: action.state, connectionDetail: action.detail };
  }
  if (action.kind === 'printer_action') {
    return { ...state, printerError: undefined };
  }
  if (action.kind === 'confirmation_answered') {
    return { ...state, confirmation: undefined };
  }
  if (action.kind === 'show') {
    return { ...state, screen: action.screen };
  }
  if (action.kind === 'report_form_reset') {
    return { ...state, reportPhoto: undefined, reportResult: undefined };
  }
  if (action.kind === 'report_sending') {
    return { ...state, reportResult: undefined };
  }
  if (action.kind === 'onboarding_action') {
    return { ...state, onboardingError: undefined };
  }
  const { type, payload } = action.envelope;
  switch (type) {
    case 'state': {
      const next = payload as StatePayload;
      return {
        ...state,
        loaded: true,
        appearance: next.appearance,
        projects: next.projects ?? [],
        projectsProblem: next.projectsProblem || undefined,
        printers: next.printers ?? [],
        error: undefined,
        highlightPrinter: next.highlightPrinter || undefined,
        stateCount: state.stateCount + 1,
        onboarding: next.onboarding,
      };
    }
    case 'screen': {
      const asked = payload as ScreenPayload;
      return {
        ...state,
        screen:
          asked.screen === 'history'
            ? { kind: 'history', back: asked.back, projectId: asked.projectId, focus: asked.focus }
            : { kind: 'home' },
      };
    }
    case 'history':
      return {
        ...state,
        history: (payload as HistoryPayload).entries ?? [],
        reportsOffered: (payload as HistoryPayload).reportsOffered,
      };
    case 'print_report_photo':
      // Cancelling the file dialog keeps the photo already there.
      return { ...state, reportPhoto: (payload as { photo?: PrintReportPhoto }).photo ?? state.reportPhoto };
    case 'print_report_result':
      return { ...state, reportResult: payload as PrintReportResult };
    case 'projects':
      return { ...state, projects: (payload as { projects: ProjectInfo[] }).projects ?? [] };
    case 'printers':
      return { ...state, printers: (payload as { printers: PrinterInfo[] }).printers ?? [] };
    case 'appearance':
      return { ...state, appearance: (payload as { appearance: Appearance }).appearance };
    case 'printer_error':
      return { ...state, printerError: payload as PrinterErrorPayload };
    case 'confirm':
      return { ...state, confirmation: payload as ConfirmPayload };
    case 'onboarding_error':
      return { ...state, onboardingError: (payload as { message?: string }).message };
    case 'bridge_error':
      return { ...state, error: (payload as { message?: string }).message };
    default:
      return state;
  }
}

