.app.connecting p {
  margin: 0;
  color: var(--text-secondary);
}

/* First-run onboarding takes the whole Home surface. Each rule below is a
   layer of the Figma frames on the "On boarding experience" page, and the
   numbers are those frames' auto-layout values. Figma draws a stroke inside
   its box, so outlines are inset shadows rather than borders: a border would
   make every card two pixels larger than its frame. */
.onboarding {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  color: var(--text-primary);
  background: var(--surface-canvas);
}

.onboarding p,
.onboarding h1,
.onboarding h2,
.onboarding dl,
.onboarding dd,
.onboarding ul {
  margin: 0;
}

.onboarding h1 {
  font: var(--font-page-title);
  color: var(--text-primary);
}


.onboarding-error {
  font: var(--font-label);
  color: var(--status-danger);
}

/* The shared buttons, as the frames draw them: a primary button has no
   outline of its own, and a secondary one shows the surface it sits on. */
.onboarding .button-primary,
.onboarding .button-secondary {
  justify-content: center;
  white-space: nowrap;
  text-decoration: none;
}

.onboarding .button-primary {
  border: 0;
}

.onboarding .button-secondary {
  background: transparent;
}

.onboarding .button-secondary:hover {
  background: var(--surface-subtle);
}

.onboarding .block {
  display: flex;
  width: 100%;
}

/* The design system's Button/Link: text only, Label Bold, action/primary.
   `flush` drops the side inset where a frame lines the label up with the
   text column, and `text` is the bare line the welcome frame uses. */
.onboarding-link {
  display: inline-flex;
  align-items: center;
  align-self: flex-start;
  height: 26px;
  padding: 0 4px;
  font: var(--font-label-bold);
  color: var(--action-primary);
  text-align: left;
  background: none;
  border: 0;
  border-radius: var(--radius-small);
  cursor: pointer;
}

.onboarding-link:hover {
  color: var(--action-primary-hover);
  text-decoration: underline;
}

.onboarding-link.flush,
.onboarding-link.text {
  padding: 0;
}

.onboarding-link.text {
  height: auto;
}

.onboarding-link.block {
  display: flex;
  align-self: stretch;
}

