import type { ConnectionState, PrinterInfo, SpoolInfo } from '../bridge/protocol';
import { printerHistoryLine } from '../history';
import { HistoryGlyph, MonitorGlyph, PrinterGlyph } from './Glyphs';
import { PrinterActions, PrinterMenu } from './PrinterMenu';

// Every card has one shape: the header, the job while one runs, three fact
// rows in a fixed order, then the action. Each line rests on something the
// host verified, and a row with nothing to say is left out rather than filled
// with a placeholder.
//
// The dot means the connection and nothing else: green for Online and
// Connected, the warning colour for Offline, no dot for Not connected. A job
// is carried by the header's job text and the progress bar.
const DOT_LABEL: Record<ConnectionState, string | undefined> = {
  online: 'Online',
  connected: 'Connected',
  offline: 'Offline',
  none: undefined,
};

// The distinct materials, in the order the spools hold them.
function materials(spools: SpoolInfo[]): string {
  const names: string[] = [];
  for (const spool of spools) {
    if (spool.material && !names.includes(spool.material)) names.push(spool.material);
  }
  return names.join(', ');
}

// A printer with nothing running and nothing wrong takes one line in the
// rail: its name, what it is doing, and what it has loaded. "Idle" rests on
// a connection; a printer the app cannot reach keeps the host's own words for
// that, such as "Not connected", with no dot. The chip opens into the full
// card, where the menu and Launch monitor are.
export function PrinterChip({ printer, onExpand }: { printer: PrinterInfo; onExpand: (id: string) => void }) {
  const idle =
    printer.state === 'idle' && (printer.connectionState === 'online' || printer.connectionState === 'connected');
  const status = idle ? 'Idle' : printer.connectionText;
  const loadedText = materials(printer.spools);
  const swatches = printer.spools.filter((spool) => spool.colour);
  return (
    <button
      type="button"
      className="printer-chip"
      aria-expanded={false}
      aria-label={status ? `${printer.name}, ${status}` : printer.name}
      onClick={() => onExpand(printer.id)}
    >
      <PrinterGlyph />
      <span className="printer-chip-name">{printer.name}</span>
      {idle && <span className="status-dot" aria-hidden="true" />}
      {status && <span className="printer-chip-status">{status}</span>}
      {(loadedText || swatches.length > 0) && (
        <span className="printer-chip-loaded">
          {loadedText}
          {swatches.map((spool, index) => (
            <span key={`${spool.colour}-${index}`} className="spool-swatch" style={{ background: spool.colour }} />
          ))}
        </span>
      )}
    </button>
  );
}

export function PrinterCard({
  printer,
  otherNames,
  actions,
  onLaunchMonitor,
  onHistory,
  highlighted,
}: {
  printer: PrinterInfo;
  otherNames: string[];
  actions: PrinterActions;
  onLaunchMonitor: (id: string) => void;
  // The Print history filtered to this printer (board history-05).
  onHistory: (id: string) => void;
  // The printer a receipt just named: the card's own CSS animation draws
  // attention to it once and ends on its own -- no timer either side manages.
