void CloudSignIn::ask_server(const std::string& endpoint, const json& body)
{
    m_asked        = endpoint;
    m_email.busy   = true;
    std::weak_ptr<Inbox> inbox = m_inbox;
    const std::uint64_t generation = m_generation;
    m_deps.post(m_server + "/ent/jusprin/v2/auth/" + endpoint, body.dump(), [inbox, generation](CloudHttpResult result) {
        if (const auto target = inbox.lock())
            target->push({generation, Inbox::Kind::Auth, {}, std::move(result)});
    });
}

bool CloudSignIn::start_email(const std::string& email)
{
    if (m_phase != CloudSignInPhase::Idle || email.empty())
        return false;
    ++m_generation;
    m_phase       = CloudSignInPhase::Email;
    m_email       = CloudEmailStep{};
    m_email.email = email;
    ask_server("email", {{"email", email}});
    return true;
}

bool CloudSignIn::submit_code(const std::string& code)
{
    if (m_phase != CloudSignInPhase::Email || m_email.busy || m_email.step != CloudEmailStep::Step::Code)
        return false;
    ask_server("code", {{"email", m_email.email}, {"code", code}});
    return true;
}

bool CloudSignIn::submit_password(const std::string& password)
{
    if (m_phase != CloudSignInPhase::Email || m_email.busy || m_email.step != CloudEmailStep::Step::Password)
        return false;
    ask_server("password", {{"email", m_email.email}, {"password", password}});
    return true;
}

bool CloudSignIn::send_code()
{
    if (m_phase != CloudSignInPhase::Email || m_email.busy || m_email.step == CloudEmailStep::Step::Asking)
        return false;
    ask_server("resend", {{"email", m_email.email}});
    return true;
}

// What an auth endpoint answered. A token goes on to the same check as the
// browser's; a refusal the person can act on stays on the step; anything
// else ends the sign-in with one generic error.
std::optional<CloudSignInOutcome> CloudSignIn::answered(CloudHttpResult http)
{
    m_email.busy = false;
    const json  body    = json::parse(http.body, nullptr, false);
    const std::string refusal = body.is_object() ? body.value("/error/code"_json_pointer, std::string()) : std::string();
    const auto  refused = [&](std::initializer_list<const char*> codes) {
        return std::any_of(codes.begin(), codes.end(), [&](const char* code) { return refusal == code; });
    };

    if (m_asked == "email" && http.status == 200 && body.is_object()) {
        const std::string method = body.value("method", "");
        if (method == "code" || method == "password") {
            m_email.step = method == "code" ? CloudEmailStep::Step::Code : CloudEmailStep::Step::Password;
            return std::nullopt;
        }
    }
    if (m_asked == "email" && refused({"too_many_codes"}))
        return failed("too_many_codes", "Too many codes were sent to this address. Try again in an hour.", true);
    if (m_asked == "resend" && http.status == 204) {
        m_email.step        = CloudEmailStep::Step::Code;
        m_email.refusal.clear();
        m_email.code_resent = true;
        return std::nullopt;
    }
    if ((m_asked == "code" || m_asked == "password") && http.status == 200 && body.is_object()) {
        const std::string token = body.value("access_token", "");
        if (!token.empty()) {
            begin_check(token);
            return std::nullopt;
        }
    }
    if ((m_asked == "code" && refused({"wrong_code", "expired_code", "too_many_tries"})) ||
        (m_asked == "password" && refused({"wrong_password", "too_many_tries"})) ||
        (m_asked == "resend" && refused({"too_many_codes"}))) {
        m_email.refusal    = refusal;
        m_email.tries_left = body.value("tries_left", 0);
        return std::nullopt;
    }
    return failed("sign_in_failed", "JusPrin couldn't sign you in. Try again.", true);
}

