    CHECK(sent.client_id == "JusPrin2");
    const std::string port = std::to_string(kCloudCallbackPort);
    CHECK(sent.port == kCloudCallbackPort);
    CHECK(sent.redirect_uri == "http://127.0.0.1:" + port + "/callback");
