// The user folder OrcaSlicer keeps its presets in: the one its settings
// name, or, when they name none, the account folder whose printers were
// saved last. OrcaSlicer signed in to a Bambu account saves under that
// account's id, not under "default".
boost::filesystem::path orca_user_folder(const boost::filesystem::path& orca_root, const std::string& configured)
{
    namespace fs        = boost::filesystem;
    const fs::path user = orca_root / PRESET_USER_DIR;
    if (!configured.empty())
        return user / configured;
    fs::path    newest = user / DEFAULT_USER_FOLDER_NAME;
    std::time_t written{0};
    if (!fs::is_directory(user))
        return newest;
    for (fs::directory_iterator folder(user), end; folder != end; ++folder) {
        const fs::path machines = folder->path() / PRESET_PRINTER_NAME;
        if (!fs::is_directory(machines))
            continue;
        for (fs::directory_iterator item(machines), none; item != none; ++item)
            if (boost::iequals(item->path().extension().string(), ".json") && fs::last_write_time(item->path()) > written) {
                written = fs::last_write_time(item->path());
                newest  = folder->path();
            }
    }
    return newest;
}

OrcaProfileSource detect_orca_profiles()
{
    namespace fs = boost::filesystem;
    OrcaProfileSource source;
    source.root = fs::path(data_dir()).parent_path() / "OrcaSlicer";
    if (!fs::is_directory(source.root) || source.root == fs::path(data_dir()))
        return source;

    std::string preset_folder;
    const fs::path config_path = source.root / "OrcaSlicer.conf";
    if (fs::is_regular_file(config_path)) {
        try {
            boost::nowide::ifstream stream(config_path.string());
            nlohmann::json config;
            stream >> config;
            preset_folder = config.value("app", nlohmann::json::object()).value("preset_folder", std::string());
        } catch (const std::exception&) {
            // The source directory is still useful as an honest empty state;
            // importing from an unknown account folder would be guesswork.
            return source;
        }
    }

    const fs::path user_root = orca_user_folder(source.root, preset_folder);
    const auto scan          = [&](const char* subdir, std::vector<std::string>& names) {
        const fs::path directory = user_root / subdir;
        if (!fs::is_directory(directory))
            return;
        std::vector<std::string> files;
        for (fs::directory_iterator item(directory), end; item != end; ++item) {
            if (fs::is_regular_file(item->path()) && boost::iequals(item->path().extension().string(), ".json"))
                files.push_back(item->path().string());
        }
        std::sort(files.begin(), files.end());
        for (const std::string& file : files)
            names.push_back(fs::path(file).stem().string());
        source.files.insert(source.files.end(), files.begin(), files.end());
    };
    // Base machine profiles first, then their material and process children.
    // Stable ordering also makes a retry deterministic.
    scan(PRESET_PRINTER_NAME, source.printer_names);
    scan(PRESET_FILAMENT_NAME, source.filament_names);
    scan(PRESET_PRINT_NAME, source.process_names);
    return source;
}

// The rest of `id` after `prefix`, or nothing when it has another prefix.
