/* The first launch takes the whole window: no Home header, the JusPrin
   lockup in the top-left corner, and the content centred in what is left.
   Each rule is a layer of the first-run boards on the canvas's "On boarding
   experience" page. */
.onboarding {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  overflow-y: auto;
  padding: 48px 24px;
  color: var(--text-primary);
  background: var(--surface-canvas);
}

.onboarding p,
.onboarding h1,
.onboarding ul,
.onboarding figure {
  margin: 0;
}

.onboarding h1 {
  font: var(--font-page-title);
}

.onboarding-lockup {
  position: absolute;
  top: 16px;
  left: 24px;
  height: var(--onboarding-lockup-height);
}

.onboarding-heading {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.onboarding-lead {
  font: var(--font-body);
  color: var(--text-secondary);
}

.onboarding-error {
  font: var(--font-label);
  color: var(--status-danger);
}

/* The design system's Button/Link: text only, Label Bold, action/primary. */
.onboarding-link {
  align-self: flex-start;
  padding: 4px 0;
  font: var(--font-label-bold);
  color: var(--action-primary);
  text-align: left;
  background: none;
  border: 0;
  cursor: pointer;
}

.onboarding-link:hover:not(:disabled) {
  color: var(--action-primary-hover);
  text-decoration: underline;
}

.onboarding-link:disabled {
  color: var(--action-disabled-text);
  cursor: default;
}

/* Welcome: the clip on the left, the words and doors on the right. */
.onboarding-welcome {
  display: flex;
  align-items: center;
  gap: 48px;
  width: 100%;
  max-width: var(--onboarding-content-width);
}

.onboarding-clip {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: var(--onboarding-clip-width);
}

.onboarding-clip video {
  display: block;
  width: var(--onboarding-clip-width);
  height: var(--onboarding-clip-height);
  object-fit: cover;
  border-radius: var(--radius-medium);
  box-shadow: var(--elevation-medium);
}

/* The CC BY 2.0 credit the clip's photos need, one tap away. */
.onboarding-credits {
  font: var(--font-label);
  color: var(--text-secondary);
}

.onboarding-credits summary {
  cursor: pointer;
}

.onboarding-credits p {
  margin-top: 4px;
}

.onboarding-pitch {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.onboarding-doors {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.onboarding-doors-label {
  font: var(--font-label);
  color: var(--text-secondary);
}

/* The one primary door: the first-month offer, selected. */
.onboarding-offer {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  padding: 16px;
  background: var(--surface-selected);
  border-radius: var(--radius-medium);
  box-shadow: inset 0 0 0 1px var(--border-subtle);
}

.onboarding-door-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font: var(--font-section);
}

.onboarding-door-detail {
  font: var(--font-body-small);
  color: var(--text-secondary);
}

.onboarding-door-button {
  margin-top: 8px;
}

/* The free doors: a name and what it costs. */
.onboarding-door {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 16px;
  color: var(--text-primary);
  text-align: left;
  background: var(--surface-subtle);
  border: 0;
  border-radius: var(--radius-medium);
  box-shadow: inset 0 0 0 1px var(--border-subtle);
  cursor: pointer;
}

.onboarding-door:hover:not(:disabled) {
  background: var(--surface-raised-hover);
}

.onboarding-door:disabled {
  color: var(--action-disabled-text);
  cursor: default;
}

.onboarding-door-name {
  font: var(--font-body-bold);
}

.onboarding-door-cost {
  font: var(--font-label);
  color: var(--text-secondary);
  white-space: nowrap;
}

.onboarding-door:disabled .onboarding-door-cost {
  color: var(--action-disabled-text);
}

.onboarding-spinner {
  flex: 0 0 auto;
  width: var(--glyph-size-large);
  height: var(--glyph-size-large);
  background: currentColor;
  -webkit-mask: url('@resources/jusprin/ui/icons/refresh-cw.svg') center / contain no-repeat;
  mask: url('@resources/jusprin/ui/icons/refresh-cw.svg') center / contain no-repeat;
  animation: onboarding-spin var(--onboarding-spin-duration) linear infinite;
}

@keyframes onboarding-spin {
  to {
    transform: rotate(360deg);
  }
