std::string OrcaHomeBackend::import_orca_printers()
{
    OrcaProfileSource source = detect_orca_profiles();
    if (source.printer_names.empty())
        return utf8(_L("JusPrin found no OrcaSlicer printers to bring. Start fresh instead."));
    PresetBundle* presets = wxGetApp().preset_bundle;
    AppConfig* config     = wxGetApp().app_config;
    Plater* plater        = wxGetApp().plater();
    if (presets == nullptr || config == nullptr || plater == nullptr)
        throw std::logic_error("Home imported printers before the app finished starting");

    presets->import_presets(
        source.files,
        [this](const std::string& name) {
            MessageDialog dialog(&m_frame,
                                 wxString::Format(_L("A profile named %s already exists. Replace it with the OrcaSlicer profile?"),
                                                  wxString::FromUTF8(name)),
                                 _L("Profile conflict"), wxYES_NO | wxNO_DEFAULT | wxICON_QUESTION);
            return dialog.ShowModal() == wxID_YES ? 1 : 0;
        },
        ForwardCompatibilitySubstitutionRule::Enable, *config);
    wxGetApp().load_current_presets();
    presets->update_compatible(PresetSelectCompatibleType::Always);
    m_frame.update_side_preset_ui();

    // import_presets leaves in `files` what it copied. A printer whose
    // vendor profile JusPrin lacks is not copied; the others still are.
    std::string first;
    for (const std::string& file : source.files)
        if (boost::filesystem::path(file).parent_path().filename() == PRESET_PRINTER_NAME) {
            first = boost::filesystem::path(file).stem().string();
            break;
        }
    if (first.empty())
        return utf8(_L("JusPrin couldn't bring these printers. OrcaSlicer was not changed. Start fresh instead."));
    SetupCommands::select_printer_preset(*plater, first);
    printer_chosen();
    return {};
}

std::string OrcaHomeBackend::assume_default_printer()
{
    Plater* plater = wxGetApp().plater();
    AppConfig* config = wxGetApp().app_config;
    if (plater == nullptr || config == nullptr)
        throw std::logic_error("Home installed a printer before the app finished starting");
    // A fresh install has no printer, and the person named none. They get
    // the bundled printer that belongs to no manufacturer, saved under its
    // own name like any other printer installed here.
    const Printers::VendorMap before = config->vendors();
    std::string problem;
    if (!SetupCommands::install_and_select_printer(*plater, "Custom", "Generic Klipper Printer", "0.4", "Generic PLA @System", problem))
        return problem;
    const std::vector<std::string> named = Printers::name_installed_printers(*plater, before);
    config->set(kOnboardingSection, kAssumedPrinter,
                named.empty() ? wxGetApp().preset_bundle->printers.get_selected_preset_name() : named.front());
    printer_chosen();
    return {};
}

ProjectList OrcaHomeBackend::recent_projects() const
{
    if (m_autosave == nullptr)
        return {};
    const auto managed = m_autosave->projects();
    // The projects folder itself could not be read; a project in it that
    // cannot be read is left out by projects() on its own. Home says so
    // instead of showing an empty gallery, and HomeHost keeps reading the
    // folder while Home is on screen.
    if (!managed)
        return {{}, utf8(_L("Your projects couldn't be loaded. JusPrin will keep trying."))};
    // Match printing jobs by the project's display name, which is what Orca
    // uses for a job. The source file may have been deleted after import.
    std::map<std::string, MachineObject*> printing_by_stem;
    if (DeviceManager* devices = wxGetApp().getDeviceManager()) {
        for (const auto& entry : devices->get_my_machine_list()) {
            MachineObject* machine = entry.second;
            if (machine == nullptr)
                continue;
            if (machine_is_printing(*machine) && !machine->subtask_name.empty())
                printing_by_stem.emplace(machine->subtask_name, machine);
        }
    }

    ProjectList listed;
    const std::vector<LivePrint> live = live_prints();
    const bool        offers_reports      = reports_offered();

    return true;
}

